/* Numa push notifications service worker.
 *
 * This is intentionally SEPARATE from the PWA app-shell service worker
 * (which is generated by vite-plugin-pwa). This worker is registered
 * explicitly by src/lib/push.ts at /push-sw.js and its ONLY job is to
 * handle Web Push events.
 *
 * Keep this file plain JS — it's served as a static asset from /public.
 */
self.addEventListener("install", (event) => {
  // Activate immediately so push handling lights up without a reload.
  event.waitUntil(self.skipWaiting());
});

self.addEventListener("activate", (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener("push", (event) => {
  // Enforce privacy again on device, including queued pushes from older servers.
  // Do not parse arbitrary payload text or persist financial deep links here.
  const payload = { title: "Numa Pro", body: "Your update is ready. Open Numa Pro to view it.", url: "/" };

  const showPromise = self.registration.showNotification(payload.title, {
    body: payload.body,
    icon: "/icon-192.png",
    badge: "/icon-192.png",
    data: { url: payload.url }
  });

  event.waitUntil(showPromise);
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();

  const targetUrl = "/"; // Old notification payload URLs are not trusted navigation targets.

  const focusPromise = self.clients
    .matchAll({ type: "window", includeUncontrolled: true })
    .then((clientList) => {
      for (const client of clientList) {
        try {
          const clientUrl = new URL(client.url);
          const targetParsed = new URL(targetUrl, self.location.origin);
          if (clientUrl.origin === targetParsed.origin && "focus" in client) {
            // Navigate the existing tab to the requested URL when possible.
            if ("navigate" in client && clientUrl.href !== targetParsed.href) {
              return client.navigate(targetParsed.href).then((c) => c && c.focus());
            }
            return client.focus();
          }
        } catch {
          // ignore malformed URLs and keep looking.
        }
      }
      if (self.clients.openWindow) {
        return self.clients.openWindow(targetUrl);
      }
      return undefined;
    });

  event.waitUntil(focusPromise);
});
